	if v != "3" || !ok { fmt.Printf("FAIL get c: %s %v\n", v, ok); return }
	c.Put("d", "4")
	_, ok = c.Get("a")
	if ok { fmt.Println("FAIL a should be evicted"); return }
	v, _ = c.Get("c")
	if v != "3" { fmt.Println("FAIL c should exist"); return }
