solution:
// LRU fields:
	cap   int
	data  map[string]string
	order []string

func NewLRU(capacity int) *LRU {
	return &LRU{cap: capacity, data: make(map[string]string), order: make([]string, 0)}
}

func (l *LRU) removeKey(key string) {
	for i, k := range l.order {
		if k == key {
			l.order = append(l.order[:i], l.order[i+1:]...)
			return
		}
	}
}

func (l *LRU) Get(key string) (string, bool) {
	v, ok := l.data[key]
	if ok {
		l.removeKey(key)
		l.order = append(l.order, key)
	}
	return v, ok
}

func (l *LRU) Put(key, value string) {
	if _, ok := l.data[key]; ok {
		l.removeKey(key)
	} else if len(l.data) >= l.cap {
		oldest := l.order[0]
		l.order = l.order[1:]
		delete(l.data, oldest)
	}
	l.data[key] = value
	l.order = append(l.order, key)
}

