func main() {
	_ = sync.WaitGroup{}
	r1 := WorkerPool([]int{1, 2, 3, 4, 5}, 3)
	sort.Ints(r1)
	want1 := []int{1, 4, 9, 16, 25}
	if len(r1) != 5 { fmt.Printf("FAIL len: %v\n", r1); return }
	for i := range r1 {
		if r1[i] != want1[i] { fmt.Printf("FAIL t1: got %v, want %v\n", r1, want1); return }
	}
	r2 := WorkerPool([]int{}, 2)
	if len(r2) != 0 { fmt.Printf("FAIL empty: %v\n", r2); return }
	r3 := WorkerPool([]int{10}, 5)
	if len(r3) != 1 || r3[0] != 100 { fmt.Printf("FAIL single: %v\n", r3); return }
