solution:
jobs := make(chan int, len(tasks))
results := make(chan int, len(tasks))
var wg sync.WaitGroup
for i := 0; i < workers; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for n := range jobs {
			results <- n * n
		}
	}()
}
for _, t := range tasks {
	jobs <- t
}
close(jobs)
wg.Wait()
close(results)
var out []int
for r := range results {
	out = append(out, r)
}
return out

