	err3 := RetryWithBackoff(func() error { return nil }, 5, 1*time.Millisecond)
	if err3 != nil { fmt.Printf("FAIL t3: %v\n", err3); return }
	// Check backoff timing (3 retries with 10ms base should take ~10+20+40=70ms minimum)
	start := time.Now()
	RetryWithBackoff(func() error { return fmt.Errorf("e") }, 3, 10*time.Millisecond)
	elapsed := time.Since(start)
